// Real streaming IO and transactional repair in marked fixtures only.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using DynastyCOT.Collection;
class CollectionLargeHistoryChecks {
 static int checks;static void Check(bool value,string label){if(!value)throw new IOException(label);checks++;}
 static void Reject(Action work,string label){try{work();}catch(IOException){checks++;return;}throw new IOException("Accepted: "+label);}
 static void Write(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text);}
 static int Main(string[] args){try{
  var elapsed=Stopwatch.StartNew();string parent=Path.GetFullPath(args[0]),root=Path.Combine(parent,"MMC");Directory.CreateDirectory(root);Write(Path.Combine(root,".cot-fixture"),"isolated");Write(Path.Combine(root,"MMCModManager.exe"),"fixture only");var fixture=new Fixture(root,parent);var store=new Ace.DynastyCOT.UserStore(Path.Combine(parent,"UserData"));typeof(Ace.DynastyCOT.UserStorage).GetField("current",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,store);
  var catalog=Json.Read<Catalog>(args[1]);var module=catalog.Get("BeyondTheField");Directory.CreateDirectory(Path.Combine(root,"Plugins/Old"));using(var input=File.OpenRead(Path.Combine(args[2],module.Current.ArchiveName)))using(var zip=new System.IO.Compression.ZipArchive(input))using(var dll=zip.GetEntry(module.FileName).Open())using(var dest=File.Create(Path.Combine(root,"Plugins",module.FileName)))dll.CopyTo(dest);File.Copy(Path.Combine(root,"Plugins",module.FileName),Path.Combine(root,"Plugins/Old/renamed.dll"));
  string legacy=Path.Combine(root,"COT-Runtime/DynastyEnhancer"),big=Path.Combine(legacy,"RuntimeHistory/42/2026/large-snapshot.json");Directory.CreateDirectory(Path.GetDirectoryName(big));const long length=1024L*1024*1024+65536;
  using(var file=new FileStream(big,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.SetLength(length);file.WriteByte(123);file.Position=length-1;file.WriteByte(125);}string originalHash=Paths.HashFile(big);
  string many=Path.Combine(legacy,"RuntimeHistory/42/2026/snapshots");Directory.CreateDirectory(many);for(int i=0;i<20017;i++)File.WriteAllText(Path.Combine(many,i.ToString("D5")+".json"),"{\"saved\":"+i+"}");
  Write(Path.Combine(legacy,"RuntimeHistory/42/accounts.json"),"original-account-identity");Write(Path.Combine(legacy,"RuntimeHistory/42/editions/2026-1.json"),"original published wording");Write(Path.Combine(legacy,"ScoutingReports/42/2026.json"),"original stored Notes");Write(store.Resolve("BeyondTheField/ScoutingReports/42/2026.json"),"current Notes remain");Write(Path.Combine(root,"Plugins/unrelated.txt"),"unrelated sentinel");
  var engine=new CollectionInstaller(catalog,fixture);var selected=new Dictionary<string,ModuleRelease>{{module.Id,module.Current}};int planMessages=0;var watch=Stopwatch.StartNew();var plan=engine.Install(root,selected,new PreparedModule[0],null,true,CancellationToken.None,s=>{planMessages++;});double planningMs=watch.Elapsed.TotalMilliseconds;
  Check(plan.Migration.Count>20000,"More than 20,000 history files admitted");Check(plan.Migration.Sum(f=>f.Bytes)>1024L*1024*1024,"More than one GiB admitted");Check(planMessages<200,"Planning progress bounded, no per-file UI flood");Check(RepairData.Summary(plan.Migration).Contains("GiB"),"Readable size in preview");
  string expected=store.Resolve("BeyondTheField/RuntimeHistory/42/2026/large-snapshot.json");long required=RepairData.RequiredSpace(plan.Migration,123456);Check(required>length+RepairData.SpaceReserve,"Space includes copies, allocation and program overhead");Reject(()=>RepairData.RequireSpace(store.Root,required,required-1),"Insufficient-space preflight rejected");RepairData.RequireSpace(store.Root,required,required);Check(true,"Exact sufficient-space boundary accepted");
  var synthetic=new[]{new MigrationFile{Source=big,Destination="BeyondTheField/huge.json",Hash=new string('a',64),Bytes=6L*1024*1024*1024}};Check(RepairData.RequiredSpace(synthetic,0)>UInt32.MaxValue,"Multi-GiB accounting remains 64-bit");
  using(var stop=new CancellationTokenSource()){stop.CancelAfter(1);bool cancelled=false;try{engine.Install(root,selected,new PreparedModule[0],null,true,stop.Token,s=>{});}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Cancellation interrupts real large-history planning");Check(!File.Exists(expected)&&File.Exists(Path.Combine(root,"Plugins/Old/renamed.dll")),"Cancelled preparation copies no history and retires no program");}
  // Failure after copy, during the first program operation: restore program
  // files while retaining additive verified data for a safe retry.
  watch.Restart();int copyMessages=0;Reject(()=>engine.Execute(plan,new Dictionary<string,string>(),s=>{copyMessages++;},1),"Injected repair interruption reports failure");double interruptedMs=watch.Elapsed.TotalMilliseconds;
  Check(File.Exists(Path.Combine(root,"Plugins/Old/renamed.dll")),"Interrupted repair restored nested provider");Check(Paths.HashFile(expected)==originalHash&&new FileInfo(expected).Length==length,"Large destination verified after interruption");Check(Paths.HashFile(big)==originalHash,"Original large history untouched");Check(copyMessages<200,"Copy progress bounded for 20k files");Check(File.ReadAllText(store.Resolve("BeyondTheField/ScoutingReports/42/2026.json"))=="current Notes remain","Current Notes never overwritten");Check(Directory.GetFiles(store.Resolve("Migration/BeyondTheField/RepairConflicts"),"*.bak").Any(p=>File.ReadAllText(p)=="original stored Notes"),"Conflicting old Notes archived intact");Check(RepairData.RequiredSpace(plan.Migration,0)==RepairData.SpaceReserve,"Retry requires no duplicate storage for already matching history");
  watch.Restart();var retry=engine.Install(root,selected,new PreparedModule[0],null,true);string backup=engine.Execute(retry,new Dictionary<string,string>(),s=>{});double retryMs=watch.Elapsed.TotalMilliseconds;Check(!File.Exists(Path.Combine(root,"Plugins/Old/renamed.dll")),"Retry retires exact duplicate");Check(File.ReadAllText(store.Resolve("BeyondTheField/RuntimeHistory/42/accounts.json"))=="original-account-identity"&&File.ReadAllText(store.Resolve("BeyondTheField/RuntimeHistory/42/editions/2026-1.json"))=="original published wording","Accounts and published words preserved");
  engine.Restore(root,backup);Check(File.Exists(Path.Combine(root,"Plugins/Old/renamed.dll")),"Explicit rollback restores duplicate");Check(Paths.HashFile(big)==originalHash&&Paths.HashFile(expected)==originalHash,"Rollback keeps original and copied large histories intact");Check(File.ReadAllText(Path.Combine(root,"Plugins/unrelated.txt"))=="unrelated sentinel","Unrelated data untouched");Check(!Directory.EnumerateFiles(store.Root,"*.tmp",SearchOption.AllDirectories).Any(),"Completed/failed copies leave no temporary files");
  // Changed source after review blocks program retirement without overwriting
  // an existing destination. Original evidence remains available.
  var stale=engine.Install(root,selected,new PreparedModule[0],null,true);Write(Path.Combine(legacy,"RuntimeHistory/42/accounts.json"),"changed after preview");Reject(()=>engine.Execute(stale,new Dictionary<string,string>(),s=>{}),"Changed source rejected before retirement");Check(File.Exists(Path.Combine(root,"Plugins/Old/renamed.dll"))&&File.ReadAllText(store.Resolve("BeyondTheField/RuntimeHistory/42/accounts.json"))=="original-account-identity","Stale preview keeps provider and current accounts");
  var edition=stale.Migration.Single(f=>f.Source.Replace('\\','/').EndsWith("editions/2026-1.json"));Write(store.Resolve(edition.Destination),"current edit after preview");Check(RepairData.RequiredSpace(new[]{edition},0)==RepairData.SpaceReserve,"Space estimation does not rehash or allocate over an existing target");Reject(()=>RepairData.Copy(root,new[]{edition},s=>{}),"Existing mismatched target still rejected by full integrity preflight");Check(File.ReadAllText(store.Resolve(edition.Destination))=="current edit after preview","Space optimization cannot overwrite changed data");Check(RepairData.RequiredSpace(synthetic.Concat(synthetic),0)==RepairData.RequiredSpace(synthetic,0),"Duplicate destinations counted once for space");
  long peak=Process.GetCurrentProcess().PeakWorkingSet64;Check(peak<512L*1024*1024,"History contents never buffered in memory");File.WriteAllBytes(Path.Combine(parent,"results.json"),Json.Bytes(new{checks=checks,files=plan.Migration.Count,bytes=plan.Migration.Sum(f=>f.Bytes),largeFileBytes=length,largeFileSha256=originalHash,planningMs=planningMs,interruptedRepairMs=interruptedMs,retryMs=retryMs,totalMs=elapsed.Elapsed.TotalMilliseconds,peakWorkingSetBytes=peak,cpuMs=Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds,planProgressMessages=planMessages,copyProgressMessages=copyMessages,liveChanges=false}));Console.WriteLine("PASS "+checks+" large-history streaming/space/cancellation/preservation/retry/rollback checks. Fixtures only.");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
